knowledge.example:
-- Query hay chạy:
SELECT id, total FROM orders
WHERE tenant_id = $1 AND status = 'paid' AND created_at >= now() - interval '7 days'
ORDER BY created_at DESC;

-- Bằng trước, range/sort sau, INCLUDE để index-only scan:
CREATE INDEX CONCURRENTLY orders_tenant_status_created
  ON orders (tenant_id, status, created_at DESC) INCLUDE (total);

-- Index này KHÔNG giúp được: WHERE status = 'paid' (thiếu tenant_id ở đầu)
EXPLAIN (ANALYZE, BUFFERS) SELECT ...;
